// Собираем человеческое сообщение о сбое. Имя сценария берём как в панели,
// из registry.json (по id воркфлоу), чтобы владелец видел знакомое название.
const d = $input.first().json;
const wf = d.workflow || {};
// Форма данных зависит от того, где упало: в запуске (execution.error)
// или при включении/триггере (trigger.error).
const ex = d.execution || {};
const err = ex.error || (d.trigger && d.trigger.error) || {};
let names = {};
try {
  const fs = require('fs');
  const reg = JSON.parse(fs.readFileSync('C:/Users/User/artmellio-system/panel/registry.json', 'utf8'));
  for (const s of reg.scenarios) names[s.workflow_id] = s.name;
} catch (e) { names = {}; }
const name = names[wf.id] || wf.name || wf.id || 'неизвестный сценарий';
const node = ex.lastNodeExecuted || '';
const msg = String(err.message || err.description || (d.trigger ? 'сценарий не смог включиться или сработать (проверьте узлы в n8n)' : 'без описания')).slice(0, 400);
const when = new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Warsaw' });
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tg = [
  `⚠️ <b>Сбой сценария: ${esc(name)}</b>`,
  node ? `Узел: ${esc(node)}` : '',
  `Ошибка: ${esc(msg)}`,
  ex.id ? `Запуск №${esc(ex.id)} · ${esc(when)}` : esc(when),
  'Подробности — в панели, кнопка «История» у сценария.',
].filter(Boolean).join('\n');
return [{ json: {
  kind: 'error',
  title: `Сбой: ${name}`,
  text: [node ? `узел «${node}»` : '', msg, ex.id ? `запуск №${ex.id}` : ''].filter(Boolean).join(' · '),
  telegram_text: tg,
  telegram_on: Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID),
} }];
